<script setup>
import { computed, ref, onMounted, onBeforeUnmount } from 'vue'
import { useLearnerStore } from '@/stores/learner'
import bank from '@/data/scene850.json'
import { SCENES,localLesson } from '@/data/lessons'
import { articlePolicy,outputPlan,knownWords } from '@/domain/learning-engine.mjs'
import { tokens } from '@/domain/progress.mjs'
import { api } from '@/services/api'
import { speakText,stopSpeaking } from '@/services/audio'
import SceneVisual from '@/components/SceneVisual.vue'
import LessonText from '@/components/LessonText.vue'
import PracticePanel from '@/components/PracticePanel.vue'
const learner=useLearnerStore(),lesson=ref(learner.lesson||localLesson(learner.settings.scene,learner.settings.length)),translation=ref(false),mode=ref(''),index=ref(0),masked=ref(false),generating=ref(false),status=ref(''),listening=ref(false),supports=ref(new Set()),textScore=ref(0),completed=ref(false),guide=ref(!learner.guideSeen),connected=ref(false)
const plan=computed(()=>outputPlan(learner.workingLevel,learner.settings.scene)),wordCount=computed(()=>tokens(lesson.value.sentences.map(r=>r[0]).join(' ')).length)
let controller,disposed=false
onMounted(async()=>{try{connected.value=(await api('status')).articleConnected}catch{};if(!learner.lesson)generate()})
onBeforeUnmount(()=>{disposed=true;controller?.abort();stopSpeaking()})
function targets(){const scene=SCENES.find(s=>s.id===learner.settings.scene);return bank.rows.filter(r=>scene.modules.includes(r.source_category)&&!['stable','active'].includes(learner.model.words[r.lookup]?.state)).sort((a,b)=>(learner.model.words[b.lookup]?.clicks||0)-(learner.model.words[a.lookup]?.clicks||0)||a.rank-b.rank).slice(0,3)}
async function generate(){
  if(generating.value)return
  stopSpeaking();listening.value=false;generating.value=true;completed.value=false;mode.value='';masked.value=false;supports.value=new Set();textScore.value=0;status.value='正在按你的词汇和场景准备文章…';controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000)
  const policy=articlePolicy(learner.workingLevel,learner.settings.length,learner.settings.challenge),confirmed=knownWords(learner.model),unknown=Object.entries(learner.model.words).filter(([,r])=>['unknown','learning'].includes(r.state)).map(([w])=>w)
  const inferred=bank.rows.filter(r=>r.rank<=learner.workingLevel&&!unknown.includes(r.lookup)).map(r=>r.lookup)
  const payload={...policy,libraryId:bank.meta.library_id,estimatedKnown:learner.summary.median,workingLevel:learner.workingLevel,scene:learner.settings.scene,outputGoal:plan.value.goal,knownVocabulary:confirmed,inferredVocabulary:inferred,targetVocabulary:targets().map(r=>r.lookup),unknownVocabulary:unknown.slice(0,60),outputGaps:learner.model.outputGaps.filter(g=>!g.resolved).slice(0,5),recentTitles:learner.sessions.slice(0,5).map(s=>s.title)}
  try{const data=await api('generate-article',payload,controller.signal);if(!disposed){lesson.value={...data,scene:learner.settings.scene,source:'AI个性化生成'};status.value='新文章已准备好';learner.saveLesson(lesson.value)}}catch(e){if(!disposed){lesson.value=localLesson(learner.settings.scene,learner.settings.length,learner.sessions.length);status.value=e.name==='AbortError'?'生成较慢，已提供本地场景课程，可再试一次。':`${e.message} 已提供本地场景课程。`;learner.saveLesson(lesson.value)}}finally{clearTimeout(timeout);generating.value=false;learner.persist()}
}
function listen(){if(listening.value){stopSpeaking();listening.value=false;return}listening.value=true;speakText(lesson.value.sentences.map(r=>r[0]).join(' '),{onEnd:()=>{listening.value=false;evidence({kind:'listening',words:lesson.value.sentences.map(r=>r[0]).join(' ')})},onError:e=>{listening.value=false;status.value=e}})}
function evidence({kind,words}){const list=Array.isArray(words)?words:tokens(words);for(const w of new Set(list)){const record=learner.model.words[w];if(!record)continue;learner.evidence(w,{[kind]:1,exposures:1,scene:learner.settings.scene})}}
function support(word){supports.value.add(word)}
function selectMode(next){stopSpeaking();listening.value=false;mode.value=mode.value===next?'':next;masked.value=mode.value==='dictation';index.value=0}
function finish(comprehension){if(completed.value)return;learner.addSession({type:'lesson',lessonId:lesson.value.id||`${lesson.value.title}-${Date.now()}`,wholePractice:mode.value==='whole'&&textScore.value>=0,title:lesson.value.title,scene:learner.settings.scene,comprehension,textScore:textScore.value,supportRatio:supports.value.size/Math.max(1,new Set(tokens(lesson.value.sentences.map(r=>r[0]).join(' '))).size),supportWords:[...supports.value],level:learner.workingLevel});completed.value=true;status.value='已记录这次学习。下一篇会参考你的卡点。';if(comprehension==='hard'){learner.workingLevel=Math.max(50,learner.workingLevel-50);learner.settings.challenge='easier';learner.persist()}}
</script>
<template><section><header class="page-head"><div><h1>今天，{{plan.goal}}。</h1><p>从舒服的输入开始，练出你能用的一句话。</p></div><RouterLink to="/chat" class="coach-link"><img src="/assets/alex-mentor.png" alt=""/><span>和 Alex 练一下</span></RouterLink></header><div v-if="guide" class="guide"><img src="/assets/alex-mentor.png" alt="Alex"/><p>先看图、听全文。不会的词直接点；整篇轻松就朗读，需要帮助就逐句练。</p><button class="btn btn-ghost" @click="guide=false;learner.guideSeen=true;learner.persist()">知道了</button></div>
<div class="lesson-toolbar"><label>场景<select v-model="learner.settings.scene" :disabled="generating" @change="generate"><option v-for="s in SCENES" :key="s.id" :value="s.id">{{s.label}}</option></select></label><label>文章长度<select v-model="learner.settings.length" :disabled="generating"><option value="short">短文章</option><option value="medium">中文章</option><option value="long">长文章</option></select></label><label>学习节奏<select v-model="learner.settings.challenge" :disabled="generating"><option value="easier">轻松一点</option><option value="just-right">刚刚好 +5%</option><option value="challenge">试着挑战 +10%</option></select></label><button class="btn btn-primary" :disabled="generating" @click="generate"><span v-if="generating" class="spinner"/>{{generating?'正在准备新文章…':'生成适合我的下一篇'}}</button></div>
<p v-if="status" class="generation-status" aria-live="polite">{{status}}</p><div class="learning-workspace"><article class="panel lesson"><SceneVisual :scene="lesson.visual||learner.settings.scene" :caption="lesson.caption"/><div class="story-head"><div><span class="section-label">{{lesson.source}}，{{wordCount}}词</span><h2 class="reading-font">{{lesson.title}}</h2></div><button class="btn btn-ghost" :disabled="masked" @click="translation=!translation">{{translation?'收起翻译':'全文翻译'}}</button></div><div class="learning-controls"><button class="btn" :class="listening?'btn-primary':'btn-secondary'" @click="listen">{{listening?'暂停领读':'听全文'}}</button><button class="btn" :class="mode==='whole'?'btn-primary':'btn-secondary'" @click="selectMode('whole')">我来朗读</button><button class="btn" :class="mode==='sentence'?'btn-primary':'btn-secondary'" @click="selectMode('sentence')">逐句练</button><button class="btn" :class="mode==='dictation'?'btn-primary':'btn-secondary'" @click="selectMode('dictation')">听写（可选）</button></div>
<LessonText :sentences="lesson.sentences" :translation="translation" :scene="learner.settings.scene" :hidden="masked" :active="mode&&mode!=='whole'?index:-1" @support="support" @select="i=>{mode='sentence';index=i}"/><PracticePanel v-if="mode" :sentences="lesson.sentences" :scene="learner.settings.scene" :mode="mode" :index="index" @next="index=(index+1)%lesson.sentences.length" @mask="v=>masked=v" @evidence="evidence" @score="v=>textScore=v"/>
<footer class="completion"><p>这一篇听懂了吗？</p><div class="actions"><button class="btn btn-secondary" :disabled="completed" @click="finish('easy')">能懂，挺轻松</button><button class="btn btn-secondary" :disabled="completed" @click="finish('right')">刚刚好</button><button class="btn btn-ghost" :disabled="completed" @click="finish('hard')">需要更简单</button></div></footer></article>
<aside class="learning-side"><section><span class="section-label">今天的表达</span><h3>{{plan.goal}}</h3><p>{{lesson.outputPrompts?.[0]||plan.mode}}</p><div class="chunks"><span v-for="chunk in lesson.chunks" :key="chunk">{{chunk}}</span></div><RouterLink to="/chat" class="btn btn-secondary">用自己的情况聊一聊</RouterLink></section><section><span class="section-label">你的学习起点</span><h3>约 {{learner.summary.median}} / 850</h3><p>区间 {{learner.summary.low}}—{{learner.summary.high}}。这次从更保守的内容开始。</p><div class="small-stats"><span><b>{{learner.counts.recognized}}</b>有识读/听读证据</span><span><b>{{learner.counts.learning}}</b>需要支持</span></div></section><section class="service-note"><span>当前：设备英语朗读</span><p>豆包音色及专业发音测评待服务开通。{{connected?'个性化文章服务已连接。':'可以先用本地场景课程。'}}</p></section><section v-if="learner.nextStep.ready"><h3>可以向前一点了。</h3><p>连续3篇跨场景练习轻松完成，建议扩大约100词的练习范围。</p><button class="btn btn-primary" @click="learner.advance();generate()">试试下一阶段</button></section></aside></div></section></template>
<style scoped>.coach-link{display:flex;align-items:center;gap:10px;font-size:13px}.coach-link img{width:38px;height:48px;object-fit:contain}.guide{display:flex;align-items:center;gap:14px;border:1px solid #dce9de;background:#f0f7f2;border-radius:14px;padding:12px 18px;margin-bottom:20px}.guide img{width:36px}.guide p{font-size:13px;margin:0;flex:1}.guide .btn{font-size:12px}.lesson-toolbar{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin-bottom:12px}.lesson-toolbar label{font-size:11px;color:var(--ink-muted);display:grid;gap:7px}.lesson-toolbar select{font-size:13px;min-height:46px}.lesson-toolbar>.btn{margin-left:auto}.generation-status{font-size:12px;color:var(--ink-muted);margin:10px 0 20px;min-height:20px}.learning-workspace{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:35px}.lesson{overflow:hidden}.lesson :deep(.scene-visual){border-radius:0}.story-head{display:flex;justify-content:space-between;padding:27px 32px 18px;align-items:center;gap:15px}.story-head h2{font-size:29px;font-weight:400;margin:8px 0}.story-head .btn{font-size:12px;padding:8px 11px;white-space:nowrap}.learning-controls{display:flex;gap:8px;flex-wrap:wrap;padding:0 32px 12px}.learning-controls .btn{min-height:39px;font-size:12px;padding:8px 12px}.learning-side section{border-bottom:1px solid var(--line);padding:12px 0 25px;margin-bottom:18px}.learning-side h3{font-size:20px;font-weight:550}.learning-side p{font-size:13px;color:var(--ink-muted);line-height:1.9}.chunks{display:grid;gap:9px;margin:17px 0 22px}.chunks span{font-family:Georgia,serif;font-size:18px;padding:8px 12px;background:#eff5f0;border-radius:9px}.learning-side .btn{font-size:12px}.small-stats{display:flex;gap:20px;font-size:11px;color:var(--ink-muted)}.small-stats b{display:block;font-size:25px;color:var(--ink);font-weight:500}.service-note{font-size:11px;color:var(--ink-muted)}.completion{border-top:1px solid var(--line);padding:21px 30px 26px}.completion p{font-size:13px;margin:0 0 12px}.completion .btn{font-size:12px}@media(max-width:950px){.learning-workspace{grid-template-columns:1fr}.learning-side{display:grid;grid-template-columns:1fr 1fr;gap:25px}}@media(max-width:750px){.lesson-toolbar>.btn{width:100%;margin:6px 0 0}.learning-side{grid-template-columns:1fr;gap:0}.story-head{padding:22px 18px 12px}.story-head h2{font-size:24px}.learning-controls{padding:0 18px}.guide{flex-wrap:wrap}.completion{padding:21px 18px}}</style>
